// The file included below is generated by bindgen and is never edited by hand, so these lints are
// relaxed for the module instead (ADR-502). `unsafe_code` is granted by the crate root.
#![allow(
    non_camel_case_types,
    non_snake_case,
    reason = "the names mirror the vendor C API"
)]
#![allow(
    unsafe_op_in_unsafe_fn,
    reason = "bindgen emits `unsafe fn` wrappers whose bodies call the foreign function directly"
)]
#![allow(
    unused,
    reason = "bindgen declares every item of the header, used or not"
)]
// The bindgen-generated bindings below are FFI declarations mirroring the
// vendor C API; they cannot carry `# Safety` docs without diverging from the
// generated output, so this lint is suppressed for the included file rather
// than the (off-limits) generated source.
#![allow(
    clippy::missing_safety_doc,
    reason = "the declarations mirror the vendor C API and cannot be edited"
)]
#![allow(
    missing_debug_implementations,
    reason = "bindgen emits the loader struct without `Debug`; the generated file is not edited"
)]
#![allow(
    clippy::allow_attributes_without_reason,
    reason = "bindgen emits `allow` attributes without a reason and the generated file is not edited"
)]

include!(concat!("bindings/", env!("BINDINGS_RS_FILENAME")));
